/**
 * DO NOT RUN THIS SCRIPT AS-IS. See create-network-pro.js's header for the
 * full explanation — same situation here: the real course id is
 * "binary-cybersecurity-professional" (not "binary-cyber-pro"), a live check
 * on 2026-08-29 found it already has 20 modules of real content, and this
 * script's module ids ("module-1".."module-7") were guessed, not verified
 * against the real structure. Do not run until that's checked against
 * Firestore directly.
 */

const admin = require("firebase-admin");
admin.initializeApp({ credential: admin.credential.applicationDefault() });

const db = admin.firestore();
const COURSE_ID = "binary-cybersecurity-professional";

// Which modules this run actually wrote, and which it left alone. The
// summary at the end reports these rather than assuming every module was
// created — createModule() skips any module that already has a title.
const written = [];
const skipped = [];

async function addFlashcards(moduleId, cards) {
  const col = db.collection("courses").doc(COURSE_ID).collection("modules").doc(moduleId).collection("flashcards");
  for (let i = 0; i < cards.length; i++) await col.doc(`card-${i + 1}`).set(cards[i]);
}

async function addQuiz(moduleId, questions) {
  const col = db.collection("courses").doc(COURSE_ID).collection("modules").doc(moduleId).collection("quiz");
  for (let i = 0; i < questions.length; i++) await col.doc(`q-${i + 1}`).set(questions[i]);
}

async function createModule(moduleId, title, order, status, flashcards, quiz) {
  const ref = db.collection("courses").doc(COURSE_ID).collection("modules").doc(moduleId);
  const existing = await ref.get();
  if (existing.exists && existing.data().title) {
    console.log(`SKIPPED ${COURSE_ID}/${moduleId} — a module with title "${existing.data().title}" already exists there.`);
    skipped.push(moduleId);
    return;
  }
  await ref.set({
    title,
    subtitle: `${flashcards.length} flashcards · ${quiz.length} questions`,
    order,
    status,
  });
  await addFlashcards(moduleId, flashcards);
  await addQuiz(moduleId, quiz);
  console.log(`${COURSE_ID}/${moduleId} ("${title}"): ${flashcards.length} flashcards, ${quiz.length} quiz questions`);
  written.push(moduleId);
}

